 */
function exportMeshToOBJ(mesh) {
    // Update world matrix
    mesh.updateMatrixWorld(true);

    // Clone mesh and apply world transform to geometry
    const clone = mesh.clone();
    clone.geometry = mesh.geometry.clone();
    clone.geometry.applyMatrix4(mesh.matrixWorld);

    // Reset transform (already baked into geometry)
    clone.position.set(0, 0, 0);
    clone.rotation.set(0, 0, 0);
    clone.quaternion.identity();
    clone.scale.set(1, 1, 1);
    clone.updateMatrix();
    clone.updateMatrixWorld(true);

    // Create temp scene and export
    const tempScene = new THREE.Scene();
    tempScene.add(clone);

    return exporter.parse(tempScene);
}

/**
 * Export a group with all its meshes merged into a single OBJ
 */
function exportGroupToOBJ(group) {
    // Collect all meshes in this group
    const meshes = [];
    group.traverse((obj) => {
        if (obj.isMesh) {
            meshes.push(obj);
        }
    });

    if (meshes.length === 0) {
        return null;
    }

    // Create temp scene and add clones of all meshes with world transforms
    const tempScene = new THREE.Scene();

    for (const mesh of meshes) {
        mesh.updateMatrixWorld(true);

        const clone = mesh.clone();
        clone.geometry = mesh.geometry.clone();
        clone.geometry.applyMatrix4(mesh.matrixWorld);

        clone.position.set(0, 0, 0);
        clone.rotation.set(0, 0, 0);
        clone.quaternion.identity();
        clone.scale.set(1, 1, 1);
        clone.updateMatrix();
        clone.updateMatrixWorld(true);

        tempScene.add(clone);
    }

    return exporter.parse(tempScene);
}

/**
 * Sanitize name for filesystem
 */
function sanitizeName(name) {
    return name.replace(/[^a-zA-Z0-9_-]/g, '_');
}

// Main execution
const root = createScene();
root.updateMatrixWorld(true);

console.log('Scene structure:');
console.log('================');

