// First pass: identify parts (Groups) and their meshes
function analyzeGroup(group, parentPartName = null) {
    const groupName = group.name || 'unnamed';

    // Skip the root group itself as a part
    if (group === root) {
        for (const child of group.children) {
            if (child.isGroup) {
                analyzeGroup(child, null);
            } else if (child.isMesh) {
                // Direct mesh under root - treat as its own part
                const meshName = child.name || 'unnamed_mesh';
                if (!parts.has(meshName)) {
                    parts.set(meshName, { group: null, meshes: [] });
                }
                parts.get(meshName).meshes.push(child);
            }
        }
        return;
    }

    // This is a part
    const partName = sanitizeName(groupName);

    // Create part entry if it doesn't exist
    if (!parts.has(partName)) {
        parts.set(partName, { group: group, meshes: [] });
    }

    // Collect direct mesh children and traverse sub-groups
    for (const child of group.children) {
        if (child.isMesh) {
            parts.get(partName).meshes.push(child);
        } else if (child.isGroup) {
            // Check if this is a significant sub-part (like cabin_X)
            // or just a helper group
            const childName = child.name || '';

            // Treat cabin_X as separate parts
            if (childName.startsWith('cabin_')) {
                analyzeGroup(child, null);
            } else {
                // Add meshes from sub-group to current part
                child.traverse((obj) => {
                    if (obj.isMesh) {
                        parts.get(partName).meshes.push(obj);
                    }
                });
            }
        }
    }
}

